// ---- src/devices/phaser.mjs --------------------------------------
// The Phaser effect: a chain of first-order allpasses swept together, mixed back with the dry.
//
// Each allpass turns the phase through half a cycle around its corner; summed with the dry
// signal, every pair of stages makes one notch, and the LFO sweeps the corners up and down the
// spectrum together. Feedback from the end of the chain to its start sharpens the notches into
// the resonant, vowel-like sweep a phaser is known for.


const MAX_STAGES = 12;

const PHASER = defineDevice({
  id: 'Phaser',
  kind: 'fx',
  version: 1,
  license: 'AGPL-3.0-only',
  processor: 'poptart-phaser',
  description: 'A phaser: up to twelve allpass stages swept by an LFO, with feedback for sharper notches.',
  channels: { in: 2, out: 2 },
  params: [
    { id: 'stages', name: 'Stages', min: 2, max: MAX_STAGES, default: 6, step: 2, rate: 'k', ui: 'number',
      description: 'Every two stages make one notch.' },
    { id: 'rate', name: 'Rate', min: 0.02, max: 10, default: 0.4, unit: 'Hz', curve: 'exp',
      active: { param: 'sync', is: 'free' } },
    { id: 'sync', name: 'Sync', default: 0, options: [...SYNC_OPTIONS], rate: 'k',
      description: 'A division of the beat overrides the rate and follows the tempo.' },
    { id: 'center', name: 'Center', min: 100, max: 8000, default: 1000, unit: 'Hz', curve: 'exp',
      description: 'The middle of the sweep.' },
    { id: 'depth', name: 'Depth', min: 0, max: 1, default: 0.7,
      description: 'How far the sweep reaches either side of the center, up to three octaves.' },
    { id: 'feedback', name: 'Feedback', min: -0.9, max: 0.9, default: 0.4 },
    { id: 'spread', name: 'Spread', min: 0, max: 1, default: 0.5,
      description: 'How far the right channel\'s sweep sits behind the left\'s.' },
    { id: 'mix', name: 'Mix', min: 0, max: 1, default: 0.5 },
  ],
});

/** One channel's chain of first-order allpasses and its feedback sample. */
class Chain {
  constructor() {
    this.z = new Float64Array(MAX_STAGES);
    this.fb = 0;
  }

  reset() { this.z.fill(0); this.fb = 0; }

  /** Runs a sample through `stages` allpasses with coefficient `a`. */
  next(x, stages, a, feedback) {
    let v = x + this.fb * feedback;
    for (let s = 0; s < stages; s++) {
      const y = -a * v + this.z[s];
      this.z[s] = v + a * y;
      v = y;
    }
    this.fb = Math.tanh(v);
    return v;
  }
}

class PhaserProcessor {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.chains = [new Chain(), new Chain()];
    this.phase = 0;
    this.bpm = 120;
  }

  setTempo(bpm) { this.bpm = bpm; }

  process(inputs, outputs, count, params) {
    const inL = inputs[0];
    const inR = inputs[1] ?? inputs[0];
    const outL = outputs[0];
    const outR = outputs[1] ?? outputs[0];
    const sync = Math.round(at(params.sync, 0));
    const stages = Math.max(2, Math.min(MAX_STAGES, Math.round(at(params.stages, 0) / 2) * 2));
    const sr = this.sampleRate;
    for (let i = 0; i < count; i++) {
      this.phase += syncedHz(sync, this.bpm, at(params.rate, i)) / sr;
      if (this.phase >= 1) this.phase -= 1;
      const center = at(params.center, i);
      const octaves = 3 * at(params.depth, i);
      const feedback = at(params.feedback, i);
      const spread = at(params.spread, i) * 0.5;
      const mix = at(params.mix, i);
      // The sweep is in octaves around the center, so it covers the same musical range at any
      // center, and the allpass coefficient comes from the swept corner.
      const hzL = center * Math.pow(2, octaves * (lfoValue(this.phase, 0) * 2 - 1));
      const hzR = center * Math.pow(2, octaves * (lfoValue(this.phase + spread, 0) * 2 - 1));
      const aL = coefficient(hzL, sr);
      const aR = coefficient(hzR, sr);
      const l = inL ? inL[i] : 0;
      const r = inR ? inR[i] : 0;
      const wetL = this.chains[0].next(l, stages, aL, feedback);
      const wetR = this.chains[1].next(r, stages, aR, feedback);
      outL[i] = l + (wetL - l) * mix;
      if (outR !== outL) outR[i] = r + (wetR - r) * mix;
    }
    if (!Number.isFinite(outL[count - 1])) for (const c of this.chains) c.reset();
  }
}

/** The first-order allpass coefficient whose phase turns through a quarter cycle at `hz`. */
function coefficient(hz, sampleRate) {
  const f = Math.min(sampleRate * 0.45, Math.max(10, hz));
  const t = Math.tan((Math.PI * f) / sampleRate);
  return (1 - t) / (1 + t);
}

// ---- src/dsp/adsr.mjs --------------------------------------------
// An ADSR envelope in SECONDS.
//
// Seconds, not a normalized 0..1 depth, because that is the decision poptart already made
// everywhere else: `.attack(0.01)` is ten milliseconds whatever the tempo is doing, and a
// pattern that changes tempo does not change its own attack times. `envscale` multiplies all
// four stages at once for the cases where somebody does want the envelope to follow the tempo.
//
// A `curve` of 0 is a straight line, negative values move fast and then level off (what an
// amplitude envelope usually wants), positive values hold back and then rush. That reading is
// the same on every stage, rising or falling - see the note in the attack.
//
// EACH STAGE HAS ITS OWN. One curve for all three is the usual shortcut and it is wrong in a
// specific, audible way: the shape an attack wants and the shape a release wants are opposite
// ends of the same control. A plucked sound is an instant attack and a long exponential decay,
// which is a hard curve on the decay and none on the attack; a swell is the reverse. With one
// control you pick which of the two to get right. `set({ curve })` still sets all three at
// once, which is what a device with one knob passes.

/** Below this, a stage is instant rather than a ramp nobody can hear. */
const MIN_STAGE_SEC = 1e-5;

/** Where the curve formula stops being worth its exponentials and a line will do. */
const CURVE_EPSILON = 1e-3;

/**
 * Shapes a 0..1 ramp. `curve` 0 is linear; the sign says which end the movement bunches at.
 * The formula is continuous through 0 - the guard is there because the exact expression divides
 * by zero, not because the shape jumps.
 */
function curveShape(t, curve) {
  if (t <= 0) return 0;
  if (t >= 1) return 1;
  if (Math.abs(curve) < CURVE_EPSILON) return t;
  return (1 - Math.exp(t * curve)) / (1 - Math.exp(curve));
}

const STAGE = Object.freeze({ IDLE: 0, ATTACK: 1, DECAY: 2, SUSTAIN: 3, RELEASE: 4 });

/**
 * One envelope generator.
 *
 * Deliberately allocation-free after construction and driven one sample at a time: it lives in
 * the audio thread, and it is written the way it would have to be written to port to a
 * SuperCollider UGen later.
 *
 * The release always starts from wherever the envelope actually is, so a note released during
 * its attack fades from the level it reached rather than jumping to the sustain level first.
 */
class Adsr {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.attack = 0.01;
    this.decay = 0.1;
    this.sustain = 0.7;
    this.release = 0.2;
    this.attackCurve = -4;
    this.decayCurve = -4;
    this.releaseCurve = -4;
    this.stage = STAGE.IDLE;
    this.value = 0;
    this.stagePos = 0;      // 0..1 through the current stage
    this.stageFrom = 0;     // the level the current stage started at
  }

  /**
   * `curve` sets all three stages, for a device that offers one control; `attackCurve`,
   * `decayCurve` and `releaseCurve` set them one at a time and win over it.
   */
  set({ attack, decay, sustain, release, curve, attackCurve, decayCurve, releaseCurve, scale = 1 }) {
    if (attack !== undefined) this.attack = Math.max(0, attack) * scale;
    if (decay !== undefined) this.decay = Math.max(0, decay) * scale;
    if (sustain !== undefined) this.sustain = Math.min(1, Math.max(0, sustain));
    if (release !== undefined) this.release = Math.max(0, release) * scale;
    if (curve !== undefined) {
      this.attackCurve = curve;
      this.decayCurve = curve;
      this.releaseCurve = curve;
    }
    if (attackCurve !== undefined) this.attackCurve = attackCurve;
    if (decayCurve !== undefined) this.decayCurve = decayCurve;
    if (releaseCurve !== undefined) this.releaseCurve = releaseCurve;
  }

  /** Starts a note. `retrigger` keeps the current level so a restart does not click to zero. */
  gateOn(retrigger = true) {
    this.stageFrom = retrigger ? this.value : 0;
    if (!retrigger) this.value = 0;
    this.stage = STAGE.ATTACK;
    this.stagePos = 0;
  }

  /** Releases a note from wherever the envelope currently is. */
  gateOff() {
    if (this.stage === STAGE.IDLE) return;
    this.stageFrom = this.value;
    this.stage = STAGE.RELEASE;
    this.stagePos = 0;
  }

  /** Silences the envelope outright - a voice being stolen, not a note ending. */
  reset() {
    this.stage = STAGE.IDLE;
    this.value = 0;
    this.stagePos = 0;
    this.stageFrom = 0;
  }

  get active() {
    return this.stage !== STAGE.IDLE;
  }

  /** One sample. Returns the envelope's level, 0..1. */
  next() {
    switch (this.stage) {
      case STAGE.ATTACK: {
        if (this.attack < MIN_STAGE_SEC) {
          this.value = 1;
          this.stage = STAGE.DECAY;
          this.stagePos = 0;
          this.stageFrom = 1;
          break;
        }
        this.stagePos += 1 / (this.attack * this.sampleRate);
        if (this.stagePos >= 1) {
          this.value = 1;
          this.stage = STAGE.DECAY;
          this.stagePos = 0;
          this.stageFrom = 1;
        } else {
          // An attack rises toward 1 from wherever it started, so a retrigger mid-note does not
          // drop the level first.
          //
          // The curve is NOT negated here, though it used to be. The negation made a negative
          // curve mean "fast then level off" on the decay and "hold back then rush" on the
          // attack - opposite readings of one number, which was survivable while a single knob
          // set all three and is not now that each stage has its own. One sign, one meaning.
          this.value = this.stageFrom + (1 - this.stageFrom) * curveShape(this.stagePos, this.attackCurve);
        }
        break;
      }
      case STAGE.DECAY: {
        if (this.decay < MIN_STAGE_SEC) {
          this.value = this.sustain;
          this.stage = STAGE.SUSTAIN;
          break;
        }
        this.stagePos += 1 / (this.decay * this.sampleRate);
        if (this.stagePos >= 1) {
          this.value = this.sustain;
          this.stage = STAGE.SUSTAIN;
        } else {
          this.value = this.stageFrom + (this.sustain - this.stageFrom) * curveShape(this.stagePos, this.decayCurve);
        }
        break;
      }
      case STAGE.SUSTAIN:
        this.value = this.sustain;
        break;
      case STAGE.RELEASE: {
        if (this.release < MIN_STAGE_SEC) {
          this.value = 0;
          this.stage = STAGE.IDLE;
          break;
        }
        this.stagePos += 1 / (this.release * this.sampleRate);
        if (this.stagePos >= 1) {
          this.value = 0;
          this.stage = STAGE.IDLE;
        } else {
          this.value = this.stageFrom * (1 - curveShape(this.stagePos, this.releaseCurve));
        }
        break;
      }
      default:
        this.value = 0;
    }
    return this.value;
  }
}

// ---- src/devices/ducker.mjs --------------------------------------
// The Ducker effect: a level dip on every beat, shaped like a compressor pumping to a kick,
// without needing the kick.
//
// The dip runs on the transport's clock - the engine tells every device the tempo and where the
// beat falls - so it is on the grid whatever is playing through it. With a sidechain patched in
// it triggers on that signal's transients instead, which is the same shape driven by a real
// kick. Either way the shape is the thing: a curve from the dip's floor back up to full over the
// length set, which is what a sidechain compressor's release does with far less to set.


const DUCKER = defineDevice({
  id: 'Ducker',
  kind: 'fx',
  version: 1,
  license: 'AGPL-3.0-only',
  processor: 'poptart-ducker',
  description: 'A level dip on the beat, or on the transients of a sidechained track: the pump of a sidechain compressor, with a shape to draw instead of a detector to fight.',
  channels: { in: 2, out: 2 },
  sidechain: true,
  params: [
    { id: 'sync', name: 'Sync', default: 8, options: [...SYNC_OPTIONS], rate: 'k',
      description: 'How often the dip happens on the clock. Ignored when a sidechain is patched in, which triggers it instead.' },
    { id: 'amount', name: 'Amount', min: 0, max: 1, default: 0.8,
      description: 'How far the level drops at the dip.' },
    { id: 'length', name: 'Length', min: 0.05, max: 1, default: 0.5,
      description: 'How much of the beat the recovery takes, as a share of the sync division - or in seconds times two when a sidechain triggers it.' },
    { id: 'attack', name: 'Attack', min: 0, max: 50, default: 2, unit: 'ms',
      description: 'How long the drop itself takes. A few milliseconds keeps it from clicking.' },
    { id: 'curve', name: 'Curve', min: -8, max: 8, default: 3, step: 0.5, ui: 'number', rate: 'k',
      description: 'The shape of the recovery: positive starts slow and rises fast at the end, which is the classic pump; negative snaps back at once.' },
    { id: 'threshold', name: 'Threshold', min: -60, max: 0, default: -24, unit: 'dB',
      description: 'The level a sidechained signal has to reach to trigger the dip.' },
  ],
});

class DuckerProcessor {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.bpm = 120;
    this.anchorSec = 0;
    this.elapsed = null;      // seconds since the last trigger, or null before the first
    this.gain = 1;
    this.lastBeat = -1;
    this.armed = true;
    this.env = 0;
    this.frames = 0;
  }

  setTempo(bpm, anchorSec = null) {
    this.bpm = bpm;
    if (anchorSec != null) this.anchorSec = anchorSec;
  }

  process(inputs, outputs, count, params, sidechain, timeSec = null) {
    const inL = inputs[0];
    const inR = inputs[1] ?? inputs[0];
    const outL = outputs[0];
    const outR = outputs[1] ?? outputs[0];
    const sync = Math.round(at(params.sync, 0));
    const period = syncedSeconds(sync, this.bpm, 0.5);
    const curve = at(params.curve, 0);
    const keyed = !!(sidechain && sidechain[0]);
    const sr = this.sampleRate;
    const attackK = 1 - Math.exp(-1 / Math.max(1, at(params.attack, 0) * 0.001 * sr));
    const threshold = Math.pow(10, at(params.threshold, 0) / 20);
    const releaseK = 1 - Math.exp(-1 / (0.05 * sr));
    for (let i = 0; i < count; i++) {
      // Where this sample sits on the clock: a trigger fires when the beat index changes.
      if (keyed) {
        const key = Math.abs(sidechain[0][i]);
        this.env += (key - this.env) * (key > this.env ? 0.5 : releaseK);
        if (this.armed && this.env > threshold) { this.elapsed = 0; this.armed = false; }
        if (this.env < threshold * 0.5) this.armed = true;
      } else {
        const t = (timeSec ?? this.frames / sr) - this.anchorSec;
        const beat = Math.floor(t / period);
        if (beat !== this.lastBeat) { this.elapsed = this.lastBeat < 0 ? null : 0; this.lastBeat = beat; }
      }
      this.frames += 1;
      const amount = at(params.amount, i);
      const length = at(params.length, i) * (keyed ? 2 : period);
      let target = 1;
      if (this.elapsed != null) {
        const x = Math.min(1, this.elapsed / Math.max(0.001, length));
        target = 1 - amount * (1 - curveShape(x, curve));
        this.elapsed += 1 / sr;
      }
      // Down at the attack, up at the shape's own pace.
      this.gain += (target - this.gain) * (target < this.gain ? attackK : 1);
      const g = this.gain;
      outL[i] = (inL ? inL[i] : 0) * g;
      if (outR !== outL) outR[i] = (inR ? inR[i] : 0) * g;
    }
  }
}

// ---- src/devices/overdrive.mjs -----------------------------------
// The Overdrive effect: distortion applied to one region of the spectrum and nothing else.
//
// The signal is split at two corners - a highpass under the region, a lowpass over it - and only
// what lies between is driven; what lies outside passes clean and is added back. That is what
// keeps a driven bass from turning to mud below and fizz above, and it is what the region
// controls are for. A dynamics control compresses the region before the drive, so the grit is
// steady across a part rather than only on its loudest notes.


const OVERDRIVE = defineDevice({
  id: 'Overdrive',
  kind: 'fx',
  version: 1,
  license: 'AGPL-3.0-only',
  processor: 'poptart-overdrive',
  description: 'Overdrive on one region of the spectrum: what lies between the two corners is driven, and what lies outside passes clean.',
  channels: { in: 2, out: 2 },
  params: [
    { id: 'low', name: 'Low', min: 20, max: 20000, default: 80, unit: 'Hz', curve: 'exp', group: 'Region',
      description: 'The bottom of the driven region.' },
    { id: 'high', name: 'High', min: 20, max: 20000, default: 4000, unit: 'Hz', curve: 'exp', group: 'Region',
      description: 'The top of the driven region.' },
    { id: 'drive', name: 'Drive', min: 0, max: 48, default: 12, unit: 'dB', curve: 'pow', curveExp: 2, group: 'Drive' },
    { id: 'tone', name: 'Tone', min: 200, max: 20000, default: 6000, unit: 'Hz', curve: 'exp', group: 'Drive',
      description: 'A lowpass on the driven region after the curve.' },
    { id: 'dynamics', name: 'Dynamics', min: 0, max: 1, default: 0.3, group: 'Drive',
      description: 'Compresses the region before it is driven, so quiet notes are driven as hard as loud ones.' },
    { id: 'mix', name: 'Mix', min: 0, max: 1, default: 1, group: 'Drive' },
  ],
  figures: [
    {
      id: 'region',
      kind: 'band',
      group: 'Region',
      title: 'region',
      description: 'The driven region of the spectrum. Drag either edge.',
      params: { low: 'low', high: 'high' },
      drag: { x: 'low' },
    },
  ],
  panel: { width: 640, rows: [['Region', 'Drive']] },
});

const LOWPASS = BIQUAD_TYPES.indexOf('lowpass');
const HIGHPASS = BIQUAD_TYPES.indexOf('highpass');

/** One channel: the region's two corners, the level detector, the tone. */
class DriveChannel {
  constructor(sampleRate) {
    this.hp = new Biquad();
    this.lp = new Biquad();
    this.tone = new OnePole(sampleRate);
    this.detector = new Detector(sampleRate);
    this.detector.setTimes(5, 80);
  }

  reset() { this.hp.reset(); this.lp.reset(); this.tone.reset(); }
}

class OverdriveProcessor {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.channels = [new DriveChannel(sampleRate), new DriveChannel(sampleRate)];
    this.last = { low: -1, high: -1, tone: -1 };
  }

  process(inputs, outputs, count, params) {
    const low = at(params.low, 0);
    const high = Math.max(low, at(params.high, 0));
    const tone = at(params.tone, 0);
    if (low !== this.last.low || high !== this.last.high || tone !== this.last.tone) {
      for (const c of this.channels) {
        // Glided across the block: the driven region is what this device is FOR, so its two
        // corners are dragged about constantly and a per-block jump is heard on every drag.
        c.hp.glideTo(HIGHPASS, low, 0, Math.SQRT1_2, this.sampleRate, count);
        c.lp.glideTo(LOWPASS, high, 0, Math.SQRT1_2, this.sampleRate, count);
        c.tone.glideTo(tone, count);
      }
      this.last = { low, high, tone };
    }
    for (let ch = 0; ch < outputs.length; ch++) {
      const out = outputs[ch];
      const input = inputs[Math.min(ch, inputs.length - 1)];
      if (!input) { out.fill(0, 0, count); continue; }
      const c = this.channels[Math.min(ch, 1)];
      for (let i = 0; i < count; i++) {
        const x = input[i];
        const region = c.lp.next(c.hp.next(x));
        const rest = x - region;
        // The dynamics: a gentle upward lift on the region toward a fixed level.
        const dyn = at(params.dynamics, i);
        const env = c.detector.next(Math.abs(region));
        const lift = dyn > 0 ? Math.pow(Math.max(1e-4, env) / 0.25, -0.7 * dyn) : 1;
        const drive = dbToGain(at(params.drive, i));
        const driven = Math.tanh(region * Math.min(lift, 16) * drive) / Math.tanh(Math.min(drive, 4) * 0.5 + 0.5);
        const wet = c.tone.next(driven) * 0.7 + rest;
        const mix = at(params.mix, i);
        out[i] = x + (wet - x) * mix;
      }
      if (!Number.isFinite(out[count - 1])) c.reset();
    }
  }
}

// ---- src/devices/multiband.mjs -----------------------------------
// The Multiband effect: three-band compression, downward and upward at once.
//
// Two crossovers split the signal into low, mid and high; each band is compressed toward its
// own threshold from both directions - loud parts pulled down at the ratio, quiet parts lifted
// toward the threshold by the upward amount - and the bands are summed back. With the upward
// amounts up, deep ratios and fast times that is the sound of a squashed, hyper-present mix
// everybody has heard on a lead; with them down it is an ordinary multiband compressor. The
// amount control scales every gain change at once, so one knob takes it from off to all the way.


const BANDS = ['Low', 'Mid', 'High'];

/**
 * The four defaults each band starts on: a low band wants slower times than a high one, because
 * a slow attack on a high band lets the transient of every hat through and a fast one on a low
 * band chases the waveform of the bass itself and distorts it.
 */
const BAND_TIMES = Object.freeze({ Low: [10, 120], Mid: [3, 60], High: [1, 30] });

function compressorBandParams(name) {
  const group = name;
  const id = name.toLowerCase();
  const [attack, release] = BAND_TIMES[name];
  return [
    { id: `${id}.threshold`, name: `${name} Threshold`, min: -60, max: 0, default: -24, unit: 'dB', group },
    { id: `${id}.ratio`, name: `${name} Ratio`, min: 1, max: 20, default: 6, unit: 'x', curve: 'exp', group },
    { id: `${id}.upward`, name: `${name} Upward`, min: 0, max: 1, default: 0.7, group,
      description: 'How far a quiet signal is lifted toward the threshold. Zero is an ordinary downward compressor.' },
    // Its OWN times. One pair for all three bands is the usual shortcut and it is wrong here for
    // the reason a multiband exists at all: the bass and the cymbals are on different time
    // scales, and a setting that follows one of them mangles the other.
    { id: `${id}.attack`, name: `${name} Attack`, min: 0.1, max: 200, default: attack, unit: 'ms', curve: 'exp', rate: 'k', group },
    { id: `${id}.release`, name: `${name} Release`, min: 5, max: 2000, default: release, unit: 'ms', curve: 'exp', rate: 'k', group },
    { id: `${id}.gain`, name: `${name} Gain`, min: -24, max: 24, default: 0, unit: 'dB', group },
  ];
}

const MULTIBAND = defineDevice({
  id: 'Multiband',
  kind: 'fx',
  version: 1,
  license: 'AGPL-3.0-only',
  processor: 'poptart-multiband',
  description: 'Three-band compression that works from both directions: loud parts pulled down, quiet parts lifted up, per band. At its defaults it is the deep upward-and-downward squash; turn the upward amounts down for an ordinary multiband compressor.',
  channels: { in: 2, out: 2 },
  params: [
    { id: 'amount', name: 'Amount', min: 0, max: 1, default: 1, group: 'Global',
      description: 'Scales every gain change at once, from off to the full effect.' },
    { id: 'lowsplit', name: 'Low Split', min: 40, max: 2000, default: 200, unit: 'Hz', curve: 'exp', group: 'Global' },
    { id: 'highsplit', name: 'High Split', min: 500, max: 12000, default: 2500, unit: 'Hz', curve: 'exp', group: 'Global' },
    { id: 'mix', name: 'Mix', min: 0, max: 1, default: 1, group: 'Global' },
    { id: 'output', name: 'Output', min: -24, max: 24, default: 0, unit: 'dB', group: 'Global' },
    ...compressorBandParams('Low'), ...compressorBandParams('Mid'), ...compressorBandParams('High'),
  ],
  // One curve per band, at the head of that band's own controls. Three bands each pulling both
  // ways is six numbers a band, and the curve is the one picture that says what they add up to.
  figures: BANDS.map((name) => ({
    id: `${name.toLowerCase()}.curve`,
    kind: 'transfer',
    group: name,
    // No title: the picture sits under the band's own heading, which has named it already.
    title: '',
    description: 'What comes out of this band for what goes in - down from the threshold, up toward it from below. The dot is where the band is right now.',
    params: {
      threshold: `${name.toLowerCase()}.threshold`,
      ratio: `${name.toLowerCase()}.ratio`,
      upward: `${name.toLowerCase()}.upward`,
      makeup: `${name.toLowerCase()}.gain`,
    },
    drag: { x: 'threshold', y: 'ratio' },
  })),
  panel: { width: 760, rows: [['Global'], ['Low', 'Mid', 'High']] },
});

/** How far below its threshold a band is still lifted: quieter than this is left alone. */
const UPWARD_REACH_DB = 40;

class MultibandProcessor {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    // Two crossovers per channel: the first takes the low band off, the second splits the rest.
    this.lowX = [new Crossover(sampleRate), new Crossover(sampleRate)];
    this.highX = [new Crossover(sampleRate), new Crossover(sampleRate)];
    this.detectors = BANDS.map(() => new Detector(sampleRate));
    this.split = [new Float64Array(2), new Float64Array(2)];
    this.bands = [new Float64Array(3), new Float64Array(3)];
    this.last = { low: -1, high: -1, attack: [-1, -1, -1], release: [-1, -1, -1] };
    // Per band: the loudest the detector saw this block, and the deepest gain change - what the
    // panel draws on each band's curve.
    this.levels = [-120, -120, -120];
    this.changes = [0, 0, 0];
  }

  process(inputs, outputs, count, params) {
    const low = at(params.lowsplit, 0);
    const high = Math.max(low * 1.5, at(params.highsplit, 0));
    if (low !== this.last.low || high !== this.last.high) {
      // Glided across the block: a crossover that jumps steps the whole spectrum at once, which
      // is the loudest zipper of the lot.
      this.lowX[0].setFrequency(low, count); this.lowX[1].follow(this.lowX[0]);
      this.highX[0].setFrequency(high, count); this.highX[1].follow(this.highX[0]);
      this.last.low = low; this.last.high = high;
    }
    // Each band follows its own pair of times.
    for (let b = 0; b < BANDS.length; b++) {
      const id = BANDS[b].toLowerCase();
      const attack = at(params[`${id}.attack`], 0);
      const release = at(params[`${id}.release`], 0);
      if (attack !== this.last.attack[b] || release !== this.last.release[b]) {
        this.detectors[b].setTimes(attack, release);
        this.last.attack[b] = attack;
        this.last.release[b] = release;
      }
    }
    const inL = inputs[0];
    const inR = inputs[1] ?? inputs[0];
    const outL = outputs[0];
    const outR = outputs[1] ?? outputs[0];
    const bandIds = ['low', 'mid', 'high'];
    for (let i = 0; i < count; i++) {
      const l = inL ? inL[i] : 0;
      const r = inR ? inR[i] : 0;
      // Split both channels into their three bands.
      this.lowX[0].split(l, this.split[0]);
      this.bands[0][0] = this.split[0][0];
      this.highX[0].split(this.split[0][1], this.split[0]);
      this.bands[0][1] = this.split[0][0];
      this.bands[0][2] = this.split[0][1];
      this.lowX[1].split(r, this.split[1]);
      this.bands[1][0] = this.split[1][0];
      this.highX[1].split(this.split[1][1], this.split[1]);
      this.bands[1][1] = this.split[1][0];
      this.bands[1][2] = this.split[1][1];

      const amount = at(params.amount, i);
      let sumL = 0;
      let sumR = 0;
      if (i === 0) { this.levels.fill(-120); this.changes.fill(0); }
      for (let b = 0; b < 3; b++) {
        const id = bandIds[b];
        const key = Math.max(Math.abs(this.bands[0][b]), Math.abs(this.bands[1][b]));
        const level = dbOf(this.detectors[b].next(key));
        const threshold = at(params[`${id}.threshold`], i);
        const ratio = at(params[`${id}.ratio`], i);
        let change = gainComputer(level, threshold, ratio, 6);
        const upward = at(params[`${id}.upward`], i);
        if (upward > 0 && level < threshold) {
          const below = Math.min(UPWARD_REACH_DB, threshold - level);
          // Lifted by the same law, mirrored: the further below, the more lift, up to the reach,
          // then tapering back to nothing so silence is not raised to the threshold.
          const taper = below >= UPWARD_REACH_DB ? 0 : 1 - below / UPWARD_REACH_DB;
          change += below * (1 - 1 / ratio) * upward * taper;
        }
        if (level > this.levels[b]) this.levels[b] = level;
        if (change < this.changes[b]) this.changes[b] = change;
        const g = dbToGain(change * amount + at(params[`${id}.gain`], i));
        sumL += this.bands[0][b] * g;
        sumR += this.bands[1][b] * g;
      }
      const mix = at(params.mix, i);
      const out = dbToGain(at(params.output, i));
      outL[i] = (l + (sumL - l) * mix) * out;
      if (outR !== outL) outR[i] = (r + (sumR - r) * mix) * out;
    }
    if (!Number.isFinite(outL[count - 1])) {
      for (const x of [...this.lowX, ...this.highX]) x.reset();
    }
  }

  /** Where each band sits on its own curve, for the three pictures the panel draws. */
  report() {
    const meters = {};
    BANDS.forEach((name, b) => {
      meters[`${name.toLowerCase()}.curve`] = { inDb: this.levels[b], grDb: this.changes[b] };
    });
    return { meters };
  }
}

// ---- src/devices/stutter.mjs -------------------------------------
// The Stutter effect: catches a slice of what is playing and repeats it on the grid.
//
// The incoming audio is written into a buffer without pause. Every interval on the transport's
// clock the effect may - with the chance set - grab the slice that just went by, one grid
// division long, and play it over and over for the number of repeats, each one quieter and
// lower than the last if asked. The chance is decided by a hash of the beat it falls on, so a
// song stutters in the same places every time it is played.


const REPEAT_MAX_SEC = 4;

const STUTTER = defineDevice({
  id: 'Stutter',
  kind: 'fx',
  version: 1,
  license: 'AGPL-3.0-only',
  processor: 'poptart-stutter',
  description: 'A stutter on the grid: every interval, with the chance set, the last grid division of audio is caught and repeated, falling in level and pitch if asked.',
  channels: { in: 2, out: 2 },
  params: [
    { id: 'interval', name: 'Interval', default: 12, options: [...SYNC_OPTIONS], rate: 'k',
      description: 'How often a repeat may start.' },
    { id: 'grid', name: 'Grid', default: 2, options: [...SYNC_OPTIONS], rate: 'k',
      description: 'How long the caught slice is.' },
    { id: 'chance', name: 'Chance', min: 0, max: 1, default: 1,
      description: 'The odds a given interval repeats. Decided per beat rather than per play, so a song repeats in the same places every time.' },
    { id: 'repeats', name: 'Repeats', min: 1, max: 32, default: 8, step: 1, rate: 'k', ui: 'number' },
    { id: 'decay', name: 'Decay', min: 0, max: 1, default: 0,
      description: 'How much quieter each repeat is than the one before.' },
    { id: 'pitch', name: 'Pitch', min: -12, max: 0, default: 0, unit: 'st', step: 1, ui: 'number',
      description: 'How far each repeat drops in pitch from the one before, in semitones.' },
    { id: 'mode', name: 'Mode', default: 0, options: ['insert', 'mix'], rate: 'k',
      description: 'Insert mutes what is playing while the repeats run; mix leaves it under them.' },
    { id: 'seed', name: 'Seed', min: 0, max: 99, default: 0, step: 1, rate: 'k', ui: 'number',
      description: 'Another seed is another pattern of chances.' },
  ],
});

/** A deterministic 0..1 for a beat and a seed - the same chance the same beat, every play. */
function hashChance(beat, seed) {
  let h = ((beat | 0) * 2654435761 + (seed | 0) * 40503 + 0x9e3779b9) >>> 0;
  h ^= h >>> 15;
  h = Math.imul(h, 2246822519) >>> 0;
  h ^= h >>> 13;
  return h / 4294967296;
}

class StutterProcessor {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    const size = Math.ceil(sampleRate * REPEAT_MAX_SEC);
    this.bufL = new Float32Array(size);
    this.bufR = new Float32Array(size);
    this.size = size;
    this.write = 0;
    this.bpm = 120;
    this.anchorSec = 0;
    this.lastInterval = -1;
    this.frames = 0;
    // The repeat in progress, if any.
    this.active = false;
    this.start = 0;          // where the slice begins in the buffer
    this.length = 0;         // the slice, in samples
    this.pos = 0;            // read position inside the slice, fractional
    this.count = 0;          // repeats played so far
    this.total = 0;
    this.fade = 0;
  }

  setTempo(bpm, anchorSec = null) {
    this.bpm = bpm;
    if (anchorSec != null) this.anchorSec = anchorSec;
  }

  process(inputs, outputs, count, params, sidechain, timeSec = null) {
    const inL = inputs[0];
    const inR = inputs[1] ?? inputs[0];
    const outL = outputs[0];
    const outR = outputs[1] ?? outputs[0];
    const sr = this.sampleRate;
    const interval = syncedSeconds(Math.round(at(params.interval, 0)), this.bpm, 2);
    const grid = Math.min(REPEAT_MAX_SEC * 0.9, syncedSeconds(Math.round(at(params.grid, 0)), this.bpm, 0.125));
    const insert = Math.round(at(params.mode, 0)) === 0;
    const seed = Math.round(at(params.seed, 0));
    const total = Math.max(1, Math.round(at(params.repeats, 0)));
    for (let i = 0; i < count; i++) {
      const l = inL ? inL[i] : 0;
      const r = inR ? inR[i] : 0;
      this.bufL[this.write] = l;
      this.bufR[this.write] = r;

      // A new interval on the clock: maybe catch the slice that just went by.
      const t = (timeSec ?? this.frames / sr) - this.anchorSec;
      const beat = Math.floor(t / interval);
      if (beat !== this.lastInterval) {
        if (this.lastInterval >= 0 && hashChance(beat, seed) < at(params.chance, i)) {
          this.length = Math.max(1, Math.round(grid * sr));
          this.start = (this.write - this.length + this.size) % this.size;
          this.pos = 0;
          this.count = 0;
          this.total = total;
          this.active = true;
        }
        this.lastInterval = beat;
      }
      this.frames += 1;

      let wetL = 0;
      let wetR = 0;
      let playing = false;
      if (this.active) {
        const decay = at(params.decay, i);
        const pitch = at(params.pitch, i);
        const level = Math.pow(1 - decay, this.count);
        const rate = Math.pow(2, (pitch * this.count) / 12);
        const p = this.pos;
        const whole = Math.floor(p);
        const frac = p - whole;
        const a = (this.start + whole) % this.size;
        const b = (a + 1) % this.size;
        // A short fade at both ends of each repeat, so the loop point does not click.
        const edge = Math.min(1, Math.min(p, this.length - p) / 64);
        wetL = (this.bufL[a] + (this.bufL[b] - this.bufL[a]) * frac) * level * edge;
        wetR = (this.bufR[a] + (this.bufR[b] - this.bufR[a]) * frac) * level * edge;
        playing = true;
        this.pos += rate;
        if (this.pos >= this.length) {
          this.pos -= this.length;
          this.count += 1;
          if (this.count >= this.total) this.active = false;
        }
      }
      this.write = (this.write + 1) % this.size;
      const dry = playing && insert ? 0 : 1;
      outL[i] = l * dry + wetL;
      if (outR !== outL) outR[i] = r * dry + wetR;
    }
  }
}

// ---- src/devices/grainecho.mjs -----------------------------------
// The Grain Echo effect: a delay whose repeats are grains.
//
// The input goes into a buffer, and grains are read out of it from around the delay time back:
// each one a short windowed piece, repitched, scattered in time by the spray, and fed back into
// the buffer so the next generation of grains reads the last. At a low density and no pitch it
// is a delay with a texture; pushed, it is a cloud.


const GRAIN_MAX_SEC = 4;
const MAX_GRAINS = 48;

const GRAINECHO = defineDevice({
  id: 'GrainEcho',
  kind: 'fx',
  version: 1,
  license: 'AGPL-3.0-only',
  processor: 'poptart-grainecho',
  description: 'A delay whose repeats are grains: short repitched windows read from around the delay time and scattered, feeding back into themselves.',
  channels: { in: 2, out: 2 },
  params: [
    { id: 'sync', name: 'Sync', default: 0, options: [...SYNC_OPTIONS], rate: 'k',
      description: 'A division of the beat overrides the time and follows the tempo.' },
    { id: 'time', name: 'Time', min: 0.01, max: 2, default: 0.25, unit: 's', curve: 'exp',
      active: { param: 'sync', is: 'free' } },
    { id: 'size', name: 'Size', min: 5, max: 500, default: 80, unit: 'ms', curve: 'exp',
      description: 'How long each grain is.' },
    { id: 'density', name: 'Density', min: 1, max: 200, default: 20, unit: 'Hz', curve: 'exp',
      description: 'How many grains start each second.' },
    { id: 'pitch', name: 'Pitch', min: -24, max: 24, default: 0, unit: 'st',
      description: 'Every grain is transposed by this.' },
    { id: 'random', name: 'Random Pitch', min: 0, max: 12, default: 0, unit: 'st',
      description: 'Each grain is transposed by up to this much more, either way.' },
    { id: 'spray', name: 'Spray', min: 0, max: 1, default: 0.2,
      description: 'How far a grain may start from the delay time, as a share of it.' },
    { id: 'feedback', name: 'Feedback', min: 0, max: 0.95, default: 0.3 },
    { id: 'spread', name: 'Spread', min: 0, max: 1, default: 0.5,
      description: 'How far grains are panned either way.' },
    { id: 'mix', name: 'Mix', min: 0, max: 1, default: 0.5 },
  ],
});

/** One grain: where it reads, how far through it is, its rate and pan. */
class DelayGrain {
  constructor() { this.on = false; this.pos = 0; this.len = 1; this.at = 0; this.rate = 1; this.l = 1; this.r = 1; }
}

class GrainEchoProcessor {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.size = Math.ceil(sampleRate * GRAIN_MAX_SEC);
    this.bufL = new Float32Array(this.size);
    this.bufR = new Float32Array(this.size);
    this.write = 0;
    this.grains = Array.from({ length: MAX_GRAINS }, () => new DelayGrain());
    this.until = 0;        // samples until the next grain starts
    this.seed = 0x2545f491;
    this.bpm = 120;
  }

  setTempo(bpm) { this.bpm = bpm; }

  /** A deterministic 0..1, so the cloud is the same cloud every play. */
  random() {
    let x = this.seed;
    x ^= x << 13; x >>>= 0; x ^= x >>> 17; x ^= x << 5; x >>>= 0;
    this.seed = x;
    return x / 4294967296;
  }

  process(inputs, outputs, count, params) {
    const inL = inputs[0];
    const inR = inputs[1] ?? inputs[0];
    const outL = outputs[0];
    const outR = outputs[1] ?? outputs[0];
    const sr = this.sampleRate;
    const sync = Math.round(at(params.sync, 0));
    for (let i = 0; i < count; i++) {
      const l = inL ? inL[i] : 0;
      const r = inR ? inR[i] : 0;
      // Start a grain when one is due.
      if (--this.until <= 0) {
        const density = at(params.density, i);
        this.until = Math.max(1, Math.round(sr / density * (0.7 + 0.6 * this.random())));
        const g = this.grains.find((x) => !x.on);
        if (g) {
          const time = Math.min(GRAIN_MAX_SEC * 0.9, syncedSeconds(sync, this.bpm, at(params.time, i)));
          const spray = at(params.spray, i) * time * (this.random() * 2 - 1);
          const back = Math.max(0.001, time + spray) * sr;
          g.len = Math.max(32, Math.round(at(params.size, i) * 0.001 * sr));
          g.pos = (this.write - back - g.len * 0.5 + this.size * 4) % this.size;
          g.at = 0;
          g.rate = Math.pow(2, (at(params.pitch, i) + at(params.random, i) * (this.random() * 2 - 1)) / 12);
          const pan = (this.random() * 2 - 1) * at(params.spread, i);
          g.l = Math.cos(((pan + 1) * Math.PI) / 4) * Math.SQRT2;
          g.r = Math.sin(((pan + 1) * Math.PI) / 4) * Math.SQRT2;
          g.on = true;
        }
      }
      let wetL = 0;
      let wetR = 0;
      for (const g of this.grains) {
        if (!g.on) continue;
        const w = 0.5 - 0.5 * Math.cos((2 * Math.PI * g.at) / g.len);
        const p = g.pos;
        const whole = Math.floor(p);
        const frac = p - whole;
        const a = whole % this.size;
        const b = (a + 1) % this.size;
        const sl = (this.bufL[a] + (this.bufL[b] - this.bufL[a]) * frac) * w;
        const sr2 = (this.bufR[a] + (this.bufR[b] - this.bufR[a]) * frac) * w;
        const mono = (sl + sr2) * 0.5;
        wetL += mono * g.l;
        wetR += mono * g.r;
        g.pos += g.rate;
        if (g.pos >= this.size) g.pos -= this.size;
        if (++g.at >= g.len) g.on = false;
      }
      const fb = at(params.feedback, i);
      this.bufL[this.write] = l + Math.tanh(wetL * fb);
      this.bufR[this.write] = r + Math.tanh(wetR * fb);
      this.write = (this.write + 1) % this.size;
      const mix = at(params.mix, i);
      outL[i] = l + (wetL - l) * mix;
      if (outR !== outL) outR[i] = r + (wetR - r) * mix;
    }
  }
}

// ---- src/devices/vocoder.mjs -------------------------------------
// The Vocoder effect: the spectrum of one signal imposed on another.
//
// The modulator is split into bands, each band's level is followed, and the carrier is split
// into the same bands and each one scaled by the modulator's level in it. The effect sits on the
// carrier's track - a synth, a pad - and `.audio("voice")` patches the modulator in; with no
// modulator patched it turns the arrangement round and treats the track as the modulator over a
// carrier of its own, so a voice track alone still speaks.


const MAX_BANDS = 32;
const BANDPASS = BIQUAD_TYPES.indexOf('bandpass');

const VOCODER = defineDevice({
  id: 'Vocoder',
  kind: 'fx',
  version: 1,
  license: 'AGPL-3.0-only',
  processor: 'poptart-vocoder',
  description: 'A channel vocoder: the sidechained signal\'s spectrum, band by band, shapes this track. With nothing sidechained the track is the modulator and the carrier is the built-in one.',
  channels: { in: 2, out: 2 },
  sidechain: true,
  params: [
    { id: 'bands', name: 'Bands', min: 8, max: MAX_BANDS, default: 16, step: 4, rate: 'k', ui: 'number' },
    { id: 'low', name: 'Low', min: 40, max: 1000, default: 100, unit: 'Hz', curve: 'exp',
      description: 'The lowest band.' },
    { id: 'high', name: 'High', min: 2000, max: 16000, default: 8000, unit: 'Hz', curve: 'exp',
      description: 'The highest band.' },
    { id: 'attack', name: 'Attack', min: 1, max: 200, default: 8, unit: 'ms', curve: 'exp' },
    { id: 'release', name: 'Release', min: 5, max: 1000, default: 60, unit: 'ms', curve: 'exp' },
    { id: 'carrier', name: 'Carrier', default: 0, options: ['track', 'saw', 'noise'], rate: 'k',
      description: 'Track uses this track as the carrier and the sidechain as the modulator. Saw and noise are built-in carriers, and then this track is the modulator.' },
    { id: 'note', name: 'Carrier Note', min: 24, max: 84, default: 48, step: 1, ui: 'number',
      description: 'The built-in saw\'s pitch.' },
    { id: 'emphasis', name: 'Emphasis', min: 0, max: 1, default: 0.5,
      description: 'Lifts the high bands, which is where the consonants live.' },
    { id: 'mix', name: 'Mix', min: 0, max: 1, default: 1 },
  ],
});

class VocoderProcessor {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.modBands = Array.from({ length: MAX_BANDS }, () => new Biquad());
    this.carBands = Array.from({ length: MAX_BANDS }, () => new Biquad());
    this.detectors = Array.from({ length: MAX_BANDS }, () => new Detector(sampleRate));
    this.centers = new Float64Array(MAX_BANDS);
    this.last = { bands: -1, low: -1, high: -1, attack: -1, release: -1 };
    this.phase = 0;
    this.seed = 0x3779b9;
  }

  _tune(bands, low, high, steps = 0) {
    for (let b = 0; b < bands; b++) {
      const hz = low * Math.pow(high / low, b / (bands - 1));
      this.centers[b] = hz;
      // Adjacent bands overlap at their skirts: the Q follows the spacing.
      const q = 1 / (Math.pow(high / low, 1 / (bands - 1)) - 1) * 1.2;
      this.modBands[b].glideTo(BANDPASS, hz, 0, q, this.sampleRate, steps);
      this.carBands[b].follow(this.modBands[b]);
    }
  }

  process(inputs, outputs, count, params, sidechain) {
    const bands = Math.max(8, Math.min(MAX_BANDS, Math.round(at(params.bands, 0) / 4) * 4));
    const low = at(params.low, 0);
    const high = at(params.high, 0);
    if (bands !== this.last.bands || low !== this.last.low || high !== this.last.high) {
      // A band COUNT change is a different bank, so it lands at once; moving the edges of the
      // same bank is a sweep and glides across the block like any other filter.
      this._tune(bands, low, high, bands === this.last.bands ? count : 0);
      this.last.bands = bands; this.last.low = low; this.last.high = high;
    }
    const attack = at(params.attack, 0);
    const release = at(params.release, 0);
    if (attack !== this.last.attack || release !== this.last.release) {
      for (const d of this.detectors) d.setTimes(attack, release);
      this.last.attack = attack; this.last.release = release;
    }
    const inL = inputs[0];
    const inR = inputs[1] ?? inputs[0];
    const side = sidechain?.[0] ?? null;
    const carrierMode = Math.round(at(params.carrier, 0));
    const useTrackAsCarrier = carrierMode === 0 && side;
    const outL = outputs[0];
    const outR = outputs[1] ?? outputs[0];
    const sr = this.sampleRate;
    const hz = 440 * Math.pow(2, (at(params.note, 0) - 69) / 12);
    for (let i = 0; i < count; i++) {
      const track = ((inL ? inL[i] : 0) + (inR ? inR[i] : 0)) * 0.5;
      let modulator;
      let carrier;
      if (useTrackAsCarrier) {
        modulator = side[i];
        carrier = track;
      } else {
        modulator = track;
        if (carrierMode === 2 || (carrierMode === 0 && !side)) {
          let x = this.seed; x ^= x << 13; x >>>= 0; x ^= x >>> 17; x ^= x << 5; x >>>= 0; this.seed = x;
          carrier = x / 2147483648 - 1;
        } else {
          this.phase += hz / sr;
          if (this.phase >= 1) this.phase -= 1;
          carrier = this.phase * 2 - 1;
        }
        if (carrierMode === 0 && !side) carrier *= 0.5;
      }
      const emphasis = at(params.emphasis, i);
      let wet = 0;
      for (let b = 0; b < bands; b++) {
        const m = this.modBands[b].next(modulator);
        const env = this.detectors[b].next(Math.abs(m));
        const c = this.carBands[b].next(carrier);
        const tilt = 1 + emphasis * 3 * (b / (bands - 1));
        wet += c * env * tilt;
      }
      wet *= 2;
      const mix = at(params.mix, i);
      const dry = useTrackAsCarrier ? track : track;
      outL[i] = dry + (wet - dry) * mix;
      if (outR !== outL) outR[i] = outL[i];
    }
    if (!Number.isFinite(outL[count - 1])) {
      for (const b of this.modBands) b.reset();
      for (const b of this.carBands) b.reset();
    }
  }
}

// ---- src/worklets/shared.mjs -------------------------------------
// What every poptart worklet needs from the descriptor it is built against.
//
// The parameter list an AudioWorkletProcessor declares and the parameter list the descriptor
// declares must be the same list, or a control exists on one side and not the other - which
// shows up as a knob that does nothing and no error anywhere. So it is generated from the
// descriptor rather than written twice.
//
// EVERY AUDIOPARAM IS A POSITION, 0..1. That is what `.param()` writes, what an LFO or an envelope
// sweeps, and what a patched audio signal adds to - one contract for every control on every
// device, the same as a plugin parameter. The DSP wants real units, so each worklet turns the
// positions it is handed into Hz, seconds, semitones and modes through the descriptor's own
// curve, per sample where a signal is moving the control and once where nothing is. That
// conversion is here, once, so a synth and an effect and a ported module all do it the same way.


/**
 * The processor's parameter descriptors, straight from the device's own.
 *
 * Every parameter becomes an AudioParam, k-rate ones included. Declaring the k-rate ones here
 * too rather than passing them over the message port means there is exactly one way a parameter
 * reaches the audio thread - and a mode that arrives a block later than the value it belongs
 * with is a bug nobody will find by reading.
 */
function parameterDescriptorsFor(descriptor) {
  return descriptor.params.map((p) => ({
    name: p.id,
    defaultValue: positionOfDefault(p),
    minValue: 0,
    maxValue: 1,
    automationRate: p.rate === 'a' ? 'a-rate' : 'k-rate',
  }));
}

/** Where a parameter's default sits, as the position its AudioParam starts at. */
function positionOfDefault(p) {
  if (p.curve === 'exp') return Math.log(p.default / p.min) / Math.log(p.max / p.min);
  if (p.curve === 'pow') return Math.pow((p.default - p.min) / (p.max - p.min), 1 / p.curveExp);
  return (p.default - p.min) / (p.max - p.min);
}

/**
 * Reads a block's worth of one parameter as a plain number.
 *
 * An AudioParam that is not being automated arrives as a single-element array, which is the
 * common case for a control nobody is moving; one that is arrives with a value per sample. A
 * device that wants the whole block keeps the array, and one that only needs a block-rate value
 * takes the first element - this is for the second kind, which is every ported module.
 */
function blockValue(values, fallback = 0) {
  if (!values || values.length === 0) return fallback;
  return values[0];
}

/**
 * Turns the positions a worklet is handed into the real values its DSP reads, in place.
 *
 * `out` is a plain object the caller keeps for the life of the processor, and `scratch` a map of
 * per-parameter Float32Arrays it also keeps: a moving control is converted into its own scratch
 * array and a still one into a number, so the hot path allocates nothing. The DSP reads the
 * result with `at()` from dsp/control.mjs, which takes either shape.
 */
function realParams(descriptor, parameters, out, scratch) {
  for (const p of descriptor.params) {
    const values = parameters[p.id];
    if (!values || values.length === 0) { out[p.id] = p.default; continue; }
    if (values.length === 1) { out[p.id] = denormalize(p, values[0]); continue; }
    let buf = scratch[p.id];
    if (!buf || buf.length < values.length) buf = scratch[p.id] = new Float32Array(values.length);
    for (let i = 0; i < values.length; i++) buf[i] = denormalize(p, values[i]);
    out[p.id] = buf;
  }
  return out;
}

/** The positions a processor last read, as `{ id: position }` - what it reports to a panel. */
function lastPositions(descriptor, parameters, out) {
  for (const p of descriptor.params) {
    const values = parameters[p.id];
    if (values && values.length) out[p.id] = values[values.length - 1];
  }
  return out;
}

/**
 * Whether a message tells a processor to shut down.
 *
 * A processor lives for exactly as long as its `process` returns true, and the browser keeps it
 * alive on that answer alone - being disconnected from everything does not end it. So a device
 * that has been replaced or removed has to be TOLD, and the alternative of guessing from a
 * silent input is worse than it looks: an effect whose track is resting between notes sees the
 * same empty input as one that has been unplugged, and a processor that returns false is gone
 * for good. Guessing wrong in that direction is a chain that goes permanently silent partway
 * through a set, which is the one failure this codebase is least willing to ship.
 */
function isDispose(message) {
  return message?.kind === 'dispose';
}

/**
 * How often a watched processor reports its parameters back, in blocks. Around thirty times a
 * second at the usual block size: enough for a picture to follow a modulator, cheap enough to
 * leave on for as long as a device window is open.
 */
const REPORT_EVERY_BLOCKS = 5;

/**
 * The part of a processor's port protocol every poptart worklet shares: a `watch` message turns
 * reporting on and off, and while it is on the processor posts the positions it last read, so
 * a panel can draw a control something else is driving where it actually is rather than where
 * it was set.
 */
class Reporter {
  constructor(port, descriptor) {
    this.port = port;
    this.descriptor = descriptor;
    this.on = false;
    this.blocks = 0;
    this.values = {};
  }

  /** Whether a message was a watch toggle, and applies it if so. */
  receive(message) {
    if (message?.kind !== 'watch') return false;
    this.on = !!message.on;
    this.blocks = 0;
    return true;
  }

  /**
   * Called once per rendered block with the parameters it was handed.
   *
   * `report` is whatever else a device has to say about what it is doing right now - a
   * granulator's grains, and nothing else so far. It rides the same message because it is the
   * same question the panel is asking: what is this device doing, as opposed to what was it set
   * to, and a second channel for it would only be a second thing to turn on and off.
   */
  tick(parameters, report = null) {
    if (!this.on) return;
    if (++this.blocks < REPORT_EVERY_BLOCKS) return;
    this.blocks = 0;
    this.port.postMessage({ kind: 'values', values: lastPositions(this.descriptor, parameters, this.values), report });
  }
}

/**
 * Turns an absolute time on the context's clock into a sample offset inside the block about to
 * be rendered.
 *
 * `currentFrame` counts samples since the context started, so this is exact rather than being
 * derived from a float second count that has already lost precision by the time a set has been
 * running for an hour. An event in the past lands at the start of the block - late is better
 * than dropped - and one at or past the end of the block comes back as is, which the caller
 * reads as "keep it for a later block".
 */
function offsetInBlock(time, currentFrame, sampleRate, blockSize) {
  if (!Number.isFinite(time)) return 0;
  const frame = Math.round(time * sampleRate) - currentFrame;
  if (frame <= 0) return 0;
  return frame;
}

// ---- src/worklets/effects.worklet.js -----------------------------
// The effects poptart wrote, as AudioWorkletProcessors.
//
// One file and one implementation for all of them, on the same reasoning as the ported
// devices' worklet: the processors differ only in which DSP they hold and which controls they
// declare, and `parameterDescriptors` is a static read once per registered name - so each
// effect registers its own name around a class that does the same thing for every one of them.
// Adding an effect is one line in the list at the bottom.
//
// The controls arrive as positions and reach the DSP as real units: see realParams() in
// shared.mjs. An effect that syncs to the tempo hears it over the port, and one that takes a
// sidechain finds it as its second input.


class EffectProcessor extends AudioWorkletProcessor {
  constructor(options, descriptor, fx) {
    super(options);
    this.descriptor = descriptor;
    this.fx = fx;
    this.alive = true;
    this.real = {};
    this.scratch = {};
    this.reporter = new Reporter(this.port, descriptor);
    if (typeof fx.setTempo === 'function') fx.setTempo(options?.processorOptions?.bpm ?? 120, options?.processorOptions?.anchorSec ?? 0);
    this.port.onmessage = (event) => this.receive(event.data);
  }

  receive(message) {
    if (!message) return;
    if (isDispose(message)) { this.alive = false; return; }
    if (this.reporter.receive(message)) return;
    if (message.kind === 'tempo' && typeof this.fx.setTempo === 'function') { this.fx.setTempo(message.bpm, message.anchorSec); return; }
    if (message.kind === 'sample' && typeof this.fx.loadSample === 'function') {
      this.fx.loadSample(message.param, message.index, message);
    }
  }

  process(inputs, outputs, parameters) {
    if (!this.alive) return false;
    const input = inputs[0] ?? [];
    const out = outputs[0];
    if (!out || out.length === 0) return true;
    const params = realParams(this.descriptor, parameters, this.real, this.scratch);
    // The clock rides along for the devices on the grid: a ducker, a beat repeat.
    this.fx.process(input, out, out[0].length, params, inputs[1] ?? null, currentTime);
    this.reporter.tick(parameters, this.fx.report?.() ?? null);
    // A quiet input is a rest, not a reason to stop: see the same note on the synth.
    return true;
  }
}

const EFFECTS = [
  [DISTORT, DistortProcessor], [CRUSH, CrushProcessor], [REVERB, ReverbProcessor], [FILTER, FilterProcessor],
  [DELAY, DelayProcessor], [COMPRESSOR, CompressorProcessor], [LIMITER, LimiterProcessor],
  [EQ, EqProcessor], [CHORUS, ChorusProcessor], [FLANGER, FlangerProcessor], [PHASER, PhaserProcessor],
  [DUCKER, DuckerProcessor], [OVERDRIVE, OverdriveProcessor], [MULTIBAND, MultibandProcessor],
  [STUTTER, StutterProcessor], [GRAINECHO, GrainEchoProcessor], [VOCODER, VocoderProcessor],
];

for (const [descriptor, Impl] of EFFECTS) {
  registerProcessor(descriptor.processor, class extends EffectProcessor {
    static get parameterDescriptors() { return parameterDescriptorsFor(descriptor); }
    constructor(options) { super(options, descriptor, new Impl(sampleRate, 128)); }
  });
}
